"""Offline presentation: full original Temenos mapping with search and table navigation."""
from pathlib import Path
import json

out=Path(__file__).resolve().parent
data=json.loads((out/'NBS_Temenos_Mapping_Review.json').read_text(encoding='utf-8'))
payload=json.dumps({'manifest':data['manifest'],'mapping':data['mapping'],'decisions':data['decisions'],'examples':data['examples']},ensure_ascii=False).replace('<','\\u003c')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NBS — Original Temenos mapping • 21 October</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f4f6f9;color:#203247;font:15px/1.55 Arial,sans-serif}header{background:#17324d;color:white;padding:24px 5vw}header h1{font-size:26px;margin:0 0 5px}header p{margin:0;color:#d3dfeb}main{max-width:1600px;margin:22px auto;padding:0 25px}nav{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}button,select,input{font:inherit;padding:9px 13px;border:1px solid #c4cfdb;border-radius:6px;background:white;color:#17324d}button{cursor:pointer}button.on{background:#17324d;color:white}article,.panel{background:white;border:1px solid #d8e0e9;border-radius:8px;padding:20px;margin-bottom:16px}h2{font-size:20px;margin:0 0 10px}h3{font-size:15px;color:#31587b;margin:8px 0}p{margin:8px 0}.muted{color:#617387;font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.6 Consolas,monospace;background:#f6f8fb;padding:12px;border-radius:5px;margin:8px 0}summary{cursor:pointer;color:#31587b}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:11px 13px;border-bottom:1px solid #e1e6ed;text-align:left;vertical-align:top}th{background:#e9eff6}td.num{white-space:nowrap;text-align:right;font-variant-numeric:tabular-nums}.flag{background:#fff6df;padding:12px;border-left:4px solid #c78e21;white-space:pre-line;font-size:13px}.controls{position:sticky;top:0;background:#f4f6f9;padding:10px 0;display:flex;gap:10px;z-index:3;flex-wrap:wrap}input{min-width:320px}.badge{font-size:12px;padding:4px 8px;background:#eaf0f7;border-radius:4px}.hidden{display:none}.intro{max-width:1100px}.intro li{margin:10px 0}@media(max-width:800px){.grid{grid-template-columns:1fr}header h1{font-size:22px}main{padding:0 12px}input{min-width:200px}}@media print{header{background:white;color:#17324d;padding:10px 0}header p{color:#203247}nav,.controls{display:none}body{background:white}article,.panel{break-inside:avoid}main{margin:0;padding:0}.hidden{display:none!important}}
</style>
<header><h1>NBS mapping • original Temenos logic</h1><p>Meeting: 21 October 2026 · Balances: 30 September 2026 · Review prepared: 20 October</p></header>
<main><nav><button class="on" onclick="view('meeting',this)">Meeting brief</button><button onclick="view('mapping',this)">Full NBS mapping</button><button onclick="view('decisions',this)">Decisions</button><button onclick="view('balances',this)">Balance examples</button><button onclick="window.print()">Print this view</button></nav>
<section id="meeting"><div class="panel intro"><h2>Start with the original Temenos rules</h2><p id="coverage"></p><ol><li>Each NBS line identifies the original Temenos worksheet and row. Read its category, sector, balance types and column conditions together with its parent conditions.</li><li>The engine's current rule appears alongside. Loan-file SIC filters, Ethix fees, product policies and inferred conditions are identified as additions.</li><li>Use the GL tool's latest completed review to support corrections. Its GL destinations do not supply missing NBS collateral, customer, risk or maturity details.</li></ol><h3>Corrections already made</h3><p>Correct source labels; withdraw forced-empty overdraft/loan selections; mark missing balance types as partial or unavailable. Earlier report runs remain historical snapshots.</p><h3>The acceptance decision</h3><p>The original NBS uses ACPTCONTRABL. The newer GL review uses DEFPAY/DEFPAYBL for acceptances and deliberately excludes ACPTBANK as the same exposure. Adding both would duplicate the exposure.</p><h3>How to present the status</h3><p>This is a complete mapping review, including unresolved items. A linked row or matching zero does not establish a reconciled regulatory balance. Review the fourteen decisions before approving changes.</p><p class="muted" id="gl"></p><p class="muted">Totals across NBS tables overlap and must not be added into a bank balance-sheet total.</p></div></section>
<section id="mapping" class="hidden"><div class="controls"><select id="table" onchange="render()"></select><input id="search" placeholder="Search item, category, sector or balance type" oninput="render()"><span id="count"></span></div><div id="items"></div></section>
<section id="decisions" class="hidden"></section><section id="balances" class="hidden"></section></main>
<script id="data" type="application/json">PAYLOAD</script><script>
const D=JSON.parse(document.getElementById('data').textContent), $=id=>document.getElementById(id);
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function view(id,btn){for(const s of ['meeting','mapping','decisions','balances'])$(s).classList.toggle('hidden',s!==id);for(const b of document.querySelectorAll('nav button'))b.classList.remove('on');btn.classList.add('on');if(id==='mapping')render()}
$('coverage').textContent=`${D.manifest.items.toLocaleString()} NBS items across ${D.manifest.tables} tables; ${D.manifest.original_linked_items.toLocaleString()} linked to original Temenos rows; ${D.manifest.items-D.manifest.original_linked_items} items need an original-row decision.`;
$('gl').textContent=`GL evidence: completed run ${D.manifest.gl_snapshot.run.id}, mapping version ${D.manifest.gl_snapshot.mapping_version.id}, ${D.manifest.gl_snapshot.run.created_at}. Original Temenos workbook: ${D.manifest.catalog_sources.T24.file_name}.`;
$('table').innerHTML='<option value="">All 50 tables</option>'+[...new Set(D.mapping.map(r=>r.table))].sort().map(t=>`<option value="${t}">Table ${t}</option>`).join('');$('table').value='010';
function render(){const q=$('search').value.toLowerCase(), t=$('table').value;const rows=D.mapping.filter(r=>(!t||r.table===t)&&(!q||JSON.stringify(r).toLowerCase().includes(q)));$('count').textContent=rows.length+' items';$('items').innerHTML=rows.map(r=>`<article><h2>${esc(r.item_code)} · ${esc(r.description)}</h2><p><b>Original Temenos:</b> ${esc(r.temenos_reference||'No unique original row located')} <span class="badge">${esc(r.current_status)}</span></p><div class="grid"><div><h3>Original line wording</h3><pre>${esc(r.original_line||'No line-level criteria recorded; inspect parents and headers.')}</pre><details><summary>Original parent and column conditions</summary><pre>${esc(r.original_parents||'(none recorded)')}</pre><pre>${esc(r.original_headers||'(none recorded)')}</pre></details></div><div><h3>Current engine selection</h3><p>${esc(r.current_evidence)}</p><p><b>Source:</b> ${esc(r.current_source||'unavailable')}</p><pre>${esc(r.current_selection||'(no executable selection)')}</pre><details><summary>Exact current balance types and signs</summary><pre>${esc(r.current_types||'(not defined)')}</pre></details></div></div>${r.review?`<div class="flag">${esc(r.review)}</div>`:''}<p class="muted">${esc(r.proposed_logic)}</p></article>`).join('')}
$('decisions').innerHTML=D.decisions.map(r=>`<article><h2>${esc(r.id)} · ${esc(r.topic)}</h2><p><b>Original:</b> ${esc(r.original_reference)} — ${esc(r.original_logic)}</p><p><b>GL / engine finding:</b> ${esc(r.gl_finding)}</p><div class="flag">${esc(r.proposal)}</div><p><b>Owner:</b> ${esc(r.owner)}</p><p class="muted">Evidence: ${esc(r.evidence)}</p></article>`).join('');
$('balances').innerHTML='<div class="panel"><h2>Worked ECB balance examples</h2><p>Signed QAR thousands from the ECB source, before presentation sign changes. No exposure families are added together.</p><div style="overflow:auto"><table><tr><th>Example</th><th>Selection / types</th><th>QAR thousand</th><th>State</th><th>Meaning</th></tr>'+D.examples.map(r=>`<tr><td>${esc(r.example)}</td><td>${esc(r.criteria)}<br><b>${esc(r.balance_types)}</b></td><td class="num">${Number(r.raw_qar_thousands).toLocaleString('en',{minimumFractionDigits:2,maximumFractionDigits:2})}</td><td>${esc(r.status)}${r.missing_types?'<br>Missing '+esc(r.missing_types):''}</td><td>${esc(r.explanation)}</td></tr>`).join('')+'</table></div></div>';
</script></html>'''.replace('PAYLOAD',payload)
(out/'NBS_Temenos_Presentation.html').write_text(html,encoding='utf-8')
print('Offline presentation written:',len(html),'characters')
